// Check if there are any free blocks
if (lfs->free_count == 0) {
    return LFS_ERR_NOSPC;
}

// Use lookahead buffer if available
if (lfs->lookahead_count > 0) {
    // Select the block with the least wear from lookahead buffer
    lfs_block_t best_block = lfs->lookahead[0];
    uint32_t min_wear = lfs->block_wear[best_block];

    for (uint32_t i = 1; i < lfs->lookahead_count; i++) {
        lfs_block_t candidate = lfs->lookahead[i];
        if (lfs->block_wear[candidate] < min_wear) {
            min_wear = lfs->block_wear[candidate];
            best_block = candidate;
        }
    }

    // Mark the block as allocated
    lfs->block_wear[best_block]++;
    lfs->free_count--;
    *block = best_block;

    // Remove from lookahead buffer
    for (uint32_t i = 0; i < lfs->lookahead_count - 1; i++) {
        if (lfs->lookahead[i] == best_block) {
            lfs->lookahead[i] = lfs->lookahead[lfs->lookahead_count - 1];
            break;
        }
    }
    lfs->lookahead_count--;
    return LFS_ERR_OK;
}

// If no lookahead buffer, find the block with least wear from free list
lfs_block_t best_block = 0;
uint32_t min_wear = std::numeric_limits<uint32_t>::max();

for (lfs_block_t block_num = 0; block_num < lfs->block_count; block_num++) {
    if (lfs->block_free[block_num] && lfs->block_wear[block_num] < min_wear) {
        min_wear = lfs->block_wear[block_num];
        best_block = block_num;
    }
}

if (best_block == 0) {
    return LFS_ERR_NOSPC;
}

// Mark the block as allocated
lfs->block_free[best_block] = false;
lfs->block_wear[best_block]++;
lfs->free_count--;
*block = best_block;

return LFS_ERR_OK;

